              : t('page.overviewDescription', {
                  defaultValue: 'Manage your client credits and transfers',
                })}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {settingsError ? (
            <Alert variant="destructive" className="mb-4">
              <AlertDescription>
                {t('settings.loadErrorPrefix', { defaultValue: 'Error loading credit expiration settings:' })}{' '}
                {getErrorMessage(settings)}
              </AlertDescription>
            </Alert>
          ) : (
            <CreditExpirationSettingsPanel settings={settings} />
          )}
          <CreditsTabs tabs={tabs} />
        </CardContent>
      </Card>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {creditExpirationEnabled && (
          <Card>
            <CardHeader>
              <CardTitle>
                {t('page.expirationSummary', { defaultValue: 'Credit Expiration Summary' })}
              </CardTitle>
              <CardDescription>
                {t('page.expirationSummaryDescription', {
                  defaultValue: 'Overview of credits expiring soon',
                })}
              </CardDescription>
            </CardHeader>
            <CardContent>
              <Skeleton className="h-40 w-full" />
            </CardContent>
          </Card>
        )}

        <Card>
          <CardHeader>
            <CardTitle>{t('page.usageTrends', { defaultValue: 'Credit Usage Trends' })}</CardTitle>
            <CardDescription>
              {t('page.usageTrendsDescription', {
                defaultValue: 'Historical credit usage patterns',
              })}
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Skeleton className="h-40 w-full" />
          </CardContent>
        </Card>
      </div>

      <CreditDetailDialog
        creditId={viewCredit?.credit_id ?? null}
        clientName={viewCredit?.client_name}
        onClose={() => setViewCredit(null)}
      />
      <EditCreditExpirationDialog
        credit={editCredit}
        onClose={() => setEditCredit(null)}
      />
      <ExpireCreditDialog
        credit={expireCreditRow}
        onClose={() => setExpireCreditRow(null)}
      />
    </div>
  );
}

