'use server'

import { tenantDb, withTransaction, getTenantContext } from '@alga-psa/db';
import { createTenantKnex } from '@alga-psa/db';
import { ICreditReconciliationReport, ITransaction, ICreditTracking, IInvoiceCharge } from '@alga-psa/types';
import { v4 as uuidv4 } from 'uuid';
import { Knex } from 'knex';
import CreditReconciliationReport from '../models/creditReconciliationReport';
import { auditLog } from '@alga-psa/db';
import { withAuth } from '@alga-psa/auth';
import { hasPermission } from '@alga-psa/auth/rbac';
import Invoice from '../models/invoice';
import {
    actionError,
    permissionError,
    type ActionMessageError,
    type ActionPermissionError,
} from '@alga-psa/ui/lib/errorHandling';

export type CreditReconciliationActionError = ActionMessageError | ActionPermissionError;

type DbRow = Record<string, any>;

type ClientCreditRow = DbRow & {
    client_id: string;
    credit_balance: number;
};

type CreditBillingSettingsRow = DbRow & {
    enable_credit_expiration?: boolean | null;
};

type CreditTransactionRow = ITransaction & DbRow;
type CreditTrackingRow = ICreditTracking & DbRow;

type CreditReconciliationTableRows = {
    clients: ClientCreditRow;
    client_billing_settings: CreditBillingSettingsRow;
    default_billing_settings: CreditBillingSettingsRow;
    transactions: CreditTransactionRow;
    credit_tracking: CreditTrackingRow;
};

function tenantScopedTable<TableName extends keyof CreditReconciliationTableRows>(
    conn: Knex | Knex.Transaction,
    tenant: string,
    tableExpression: TableName
): Knex.QueryBuilder<CreditReconciliationTableRows[TableName], CreditReconciliationTableRows[TableName][]>;
function tenantScopedTable<Row extends object = Record<string, unknown>>(
    conn: Knex | Knex.Transaction,
    tenant: string,
    tableExpression: string
): Knex.QueryBuilder<Row, Row[]>;
function tenantScopedTable(
    conn: Knex | Knex.Transaction,
    tenant: string,
    tableExpression: string
) {
    return tenantDb(conn, tenant).table(tableExpression);
}

function creditReconciliationActionErrorFrom(error: unknown): CreditReconciliationActionError | null {
    if (error instanceof Error) {
        if (error.message.startsWith('Permission denied')) {
            return permissionError(error.message);
        }
        if (error.message.startsWith('Tenant context is required')) {
            return actionError('No tenant context. Please refresh and try again.');
        }
        if (/^Client .+ not found in tenant .+$/.test(error.message)) {
            return actionError('Client not found. It may have been updated or deleted. Please refresh and try again.');
        }
        if (/^Reconciliation report .+ not found$/.test(error.message)) {
            return actionError('Reconciliation report not found. It may have been updated or deleted. Please refresh and try again.');
        }
        if (/^Reconciliation report .+ is already resolved$/.test(error.message)) {
            return actionError('This reconciliation report is already resolved. Please refresh and try again.');
        }
        if (error.message === 'Client ID is required for client-specific validation') {
            return actionError('Client ID is required for client-specific validation.');
        }
    }

    const dbError = error as { code?: string; column?: string };
    if (dbError?.code === '22P02') {
        return actionError('One of the selected reconciliation values is invalid. Please refresh and try again.');
    }
    if (dbError?.code === '23502') {
        return actionError(`Missing required reconciliation field${dbError.column ? `: ${dbError.column}` : ''}.`);
    }
    if (dbError?.code === '23503') {
        return actionError('A selected reconciliation record no longer exists. Please refresh and try again.');
    }
    if (dbError?.code === '23505') {
        return actionError('A conflicting reconciliation record already exists. Please refresh and try again.');
    }

    return null;
}

async function withCreditReconciliationActionErrors<T>(work: () => Promise<T>): Promise<T | CreditReconciliationActionError> {
    try {
        return await work();
    } catch (error) {
        const expected = creditReconciliationActionErrorFrom(error);
        if (expected) return expected;
        throw error;
    }
}

/**
 * Helper to get tenant from context, throwing if not available
 */
function requireTenant(): string {
    const tenant = getTenantContext();
    if (!tenant) {
        throw new Error('Tenant context is required. Ensure this function is called within runWithTenant() or from an authenticated server action.');
    }
    return tenant;
}

function parseRowMetadata(metadata: unknown): Record<string, any> {
    if (!metadata) return {};
    if (typeof metadata === 'string') {
        try {
            return JSON.parse(metadata);
        } catch {
            return {};
        }
    }
    return metadata as Record<string, any>;
}

/**
 * Create a reconciliation report, or update the matching open report if one
 * already exists, so re-running detection does not duplicate open reports.
 * Reports match when they target the same client and issue type; tracking-type
 * reports additionally match on the specific transaction/credit they concern.
 */
async function upsertOpenReconciliationReport(
    trx: Knex.Transaction,
    tenant: string,
    reportData: {
        client_id: string;
        expected_balance: number;
        actual_balance: number;
        difference: number;
        detection_date: string;
        metadata: Record<string, any>;
    }
): Promise<{ report_id: string }> {
    const openReports = (await tenantScopedTable(trx, tenant, 'credit_reconciliation_reports')
        .where({ client_id: reportData.client_id })
        .whereIn('status', ['open', 'in_review'])) as Array<{ report_id: string; metadata: unknown }>;

    const newMetadata = reportData.metadata;
    const issueType = newMetadata.issue_type ?? null;

    const existing = openReports.find((row) => {
        const rowMetadata = parseRowMetadata(row.metadata);
        if ((rowMetadata.issue_type ?? null) !== issueType) return false;
        if (issueType === 'missing_credit_tracking_entry') {
            return rowMetadata.transaction_id === newMetadata.transaction_id;
        }
        if (issueType === 'inconsistent_credit_remaining_amount') {
            return rowMetadata.credit_id === newMetadata.credit_id;
        }
        // Balance-discrepancy reports are keyed by client alone
        return true;
    });

    if (existing) {
        await tenantScopedTable(trx, tenant, 'credit_reconciliation_reports')
            .where({ report_id: existing.report_id })
            .update({
                expected_balance: reportData.expected_balance,
                actual_balance: reportData.actual_balance,
                difference: reportData.difference,
                detection_date: reportData.detection_date,
                metadata: JSON.stringify(newMetadata),
                updated_at: new Date().toISOString(),
            });
        return { report_id: existing.report_id };
    }

    const created = await CreditReconciliationReport.create({
        ...reportData,
        tenant,
        status: 'open',
    }, trx);
    return { report_id: created.report_id };
}

type CreditInvoicePeriodSummary = {
    invoice_date_basis: 'financial_document_date' | 'canonical_recurring_service_period';
    invoice_service_period_start: string | null;
    invoice_service_period_end: string | null;
};

function summarizeCanonicalInvoiceServicePeriods(
    invoiceCharges: IInvoiceCharge[] | undefined
): CreditInvoicePeriodSummary {
    const starts = (invoiceCharges ?? [])
        .map((charge) => charge.service_period_start)
        .filter((value): value is string => typeof value === 'string' && value.length > 0)
        .sort();
    const ends = (invoiceCharges ?? [])
        .map((charge) => charge.service_period_end)
        .filter((value): value is string => typeof value === 'string' && value.length > 0)
        .sort();

    return {
        invoice_date_basis:
            starts.length > 0 || ends.length > 0
                ? 'canonical_recurring_service_period'
                : 'financial_document_date',
        invoice_service_period_start: starts[0] ?? null,
        invoice_service_period_end: ends[ends.length - 1] ?? null,
    };
}

async function loadCreditInvoiceContext(
    trx: Knex.Transaction,
    tenant: string,
    invoiceId?: string
): Promise<CreditInvoicePeriodSummary | null> {
    if (!invoiceId) {
        return null;
    }

    const invoice = await Invoice.getById(trx, tenant, invoiceId);
    return summarizeCanonicalInvoiceServicePeriods(invoice?.invoice_charges);
}

/**
 * Validates a client's credit balance without making automatic corrections
 * Instead, it creates a reconciliation report when discrepancies are found
 *
 * NOTE: This function requires tenant context to be set via runWithTenant() or withAuth wrapper.
 * For background jobs, wrap calls with runWithTenant(tenantId, ...).
 * For UI server actions, the calling action should be wrapped with withAuth.
 *
 * @param clientId The ID of the client to validate
 * @param providedTrx Optional transaction object
 * @returns Object containing validation results and report ID if a discrepancy was found
 */
export async function validateCreditBalanceWithoutCorrection(
    clientId: string,
    providedTrx?: Knex.Transaction
): Promise<{
    isValid: boolean;
    expectedBalance: number;
    actualBalance: number;
    difference: number;
    reportId?: string;
    lastTransaction?: ITransaction;
}> {
    const tenant = requireTenant();
    const { knex } = await createTenantKnex();

    // Use provided transaction or create a new one
    const executeWithTransaction = async (trx: Knex.Transaction) => {
        // Get current date for expiration check
        const now = new Date().toISOString();

        // Check if credit expiration is enabled for this client
        const clientSettings = await tenantScopedTable(trx, tenant, 'client_billing_settings')
            .where({
                client_id: clientId
            })
            .first();

        const defaultSettings = await tenantScopedTable(trx, tenant, 'default_billing_settings')
            .first();

        // Determine if credit expiration is enabled
        // Client setting overrides default, if not specified use default
        let isCreditExpirationEnabled = true; // Default to true if no settings found
        if (typeof clientSettings?.enable_credit_expiration === 'boolean') {
            isCreditExpirationEnabled = clientSettings.enable_credit_expiration;
        } else if (typeof defaultSettings?.enable_credit_expiration === 'boolean') {
            isCreditExpirationEnabled = defaultSettings.enable_credit_expiration;
        }

        // Get all credit-related transactions
        const transactions = await tenantScopedTable(trx, tenant, 'transactions')
            .where({
                client_id: clientId,
                tenant
            })
            .whereIn('type', [
                'credit_issuance',
                'credit_application',
                'credit_adjustment',
                'credit_expiration',
                'credit_transfer',
                'credit_issuance_from_negative_invoice'
            ])
            .orderBy('created_at', 'asc');

        let calculatedBalance = 0;

        // Process transactions
        for (const tx of transactions) {
            const txAmount = Number(tx.amount);

            // Balance-side reconciliation corrections are audit markers of a
            // clients.credit_balance write, not ledger credit events — counting
            // them would double-count the correction against the ledger.
            if (tx.type === 'credit_adjustment' && parseRowMetadata(tx.metadata).reconciliation_balance_correction) {
                continue;
            }

            // For credit issuance transactions, check if they're expired (only if expiration is enabled)
            if (
                isCreditExpirationEnabled &&
                (tx.type === 'credit_issuance' || tx.type === 'credit_issuance_from_negative_invoice') &&
                txAmount > 0 &&
                tx.expiration_date &&
                tx.expiration_date < now
            ) {
                // Skip expired credits in the balance calculation
                console.log(`Skipping expired credit transaction ${tx.transaction_id} with amount ${tx.amount}`);

                // Check if there's already a credit_expiration transaction for this credit
                const existingExpiration = await tenantScopedTable(trx, tenant, 'transactions')
                    .where({
                        related_transaction_id: tx.transaction_id,
                        type: 'credit_expiration',
                        tenant
                    })
                    .first();

                // If no expiration transaction exists, create one to record the expiration
                // Note: We still create expiration transactions even in the "without correction" mode
                // because expiration is a business rule, not a correction
                if (!existingExpiration) {
                    const expirationTxId = uuidv4();
                    await tenantScopedTable(trx, tenant, 'transactions').insert({
                        transaction_id: expirationTxId,
                        client_id: clientId,
                        amount: -txAmount, // Negative amount to reduce the balance
                        type: 'credit_expiration',
                        status: 'completed',
                        description: `Credit expired (original transaction: ${tx.transaction_id})`,
                        created_at: now,
                        balance_after: calculatedBalance,
                        tenant,
                        related_transaction_id: tx.transaction_id
                    });

                    // Update credit_tracking entry to mark as expired
                    const creditTracking = await tenantScopedTable(trx, tenant, 'credit_tracking')
                        .where({
                            transaction_id: tx.transaction_id,
                            tenant
                        })
                        .first();

                    if (creditTracking) {
                        await tenantScopedTable(trx, tenant, 'credit_tracking')
                            .where({
                                credit_id: creditTracking.credit_id,
                                tenant
                            })
                            .update({
                                is_expired: true,
                                remaining_amount: 0,
                                updated_at: now
                            });
                    }

                    // Add the expiration transaction to our list so it's included in the balance calculation
                    transactions.push({
                        transaction_id: expirationTxId,
                        client_id: clientId,
                        amount: -txAmount,
                        type: 'credit_expiration',
                        status: 'completed',
                        created_at: now,
                        balance_after: calculatedBalance,
                        currency_code: tx.currency_code,
                        tenant,
                        related_transaction_id: tx.transaction_id
                    });
                }
            } else {
                // For non-expired credits or other transaction types, include in balance
                calculatedBalance += txAmount;
            }
        }

        // Get the client's current credit balance
        const [client] = await tenantScopedTable(trx, tenant, 'clients')
            .where({ client_id: clientId })
            .select('credit_balance');

        const actualBalance = Number(client.credit_balance);
        const expectedBalance = Number(calculatedBalance);
        const difference = expectedBalance - actualBalance;
        const isValid = expectedBalance === actualBalance;

        let reportId: string | undefined;

        // If there's a discrepancy, create a reconciliation report
        if (!isValid) {
            console.log(`Credit balance mismatch for tenant ${tenant}:`, {
                tenant,
                clientId,
                expectedBalance,
                actualBalance,
                difference
            });

            // Create a reconciliation report (or refresh the existing open one)
            const report = await upsertOpenReconciliationReport(trx, tenant, {
                client_id: clientId,
                expected_balance: expectedBalance,
                actual_balance: actualBalance,
                difference,
                detection_date: now,
                metadata: {
                    reconciliation_date_basis: 'financial_document_date',
                    last_transaction_id: transactions.length > 0 ? transactions[transactions.length - 1].transaction_id : undefined,
                    last_transaction_type: transactions.length > 0 ? transactions[transactions.length - 1].type : undefined,
                }
            });

            reportId = report.report_id;

            // Log the discrepancy detection in the audit log
            await auditLog(
                trx,
                {
                    userId: 'system',
                    operation: 'credit_balance_discrepancy_detected',
                    tableName: 'credit_reconciliation_reports',
                    recordId: reportId,
                    changedData: {
                        expected_balance: expectedBalance,
                        actual_balance: actualBalance,
                        difference
                    },
                    details: {
                        action: 'Credit balance discrepancy detected',
                        client_id: clientId
                    }
                }
            );
        }

        return {
            isValid,
            expectedBalance,
            actualBalance,
            difference,
            reportId,
            lastTransaction: transactions.length > 0 ? transactions[transactions.length - 1] : undefined
        };
    };

    // If a transaction is provided, use it; otherwise create a new one
    if (providedTrx) {
        return await executeWithTransaction(providedTrx);
    } else {
        return await withTransaction(knex, executeWithTransaction);
    }
}

/**
 * Validates credit tracking entries for a client to identify missing entries
 * Creates reconciliation reports for any discrepancies found
 *
 * NOTE: This function requires tenant context to be set via runWithTenant() or withAuth wrapper.
 *
 * @param clientId The ID of the client to validate
 * @param providedTrx Optional transaction object
 * @returns Object containing validation results and report IDs if discrepancies were found
 */
// Internal helper — not a direct server action endpoint
export async function validateCreditTrackingEntries(
    clientId: string,
    providedTrx?: Knex.Transaction
): Promise<{
    isValid: boolean;
    missingEntries: number;
    reportIds: string[];
}> {
    const tenant = requireTenant();
    const { knex } = await createTenantKnex();

    // Use provided transaction or create a new one
    const executeWithTransaction = async (trx: Knex.Transaction) => {
        const now = new Date().toISOString();
        const reportIds: string[] = [];

        // Get all credit-related transactions that should have corresponding tracking entries
        const transactions = await tenantScopedTable(trx, tenant, 'transactions')
            .where({
                client_id: clientId,
                tenant
            })
            .whereIn('type', [
                'credit_issuance',
                'credit_issuance_from_negative_invoice',
                'credit_transfer'
            ])
            .where('amount', '>', 0) // Only positive credit transactions should have tracking entries
            .orderBy('created_at', 'asc');

        // Get all credit tracking entries for this client
        const creditTrackingEntries = await tenantScopedTable(trx, tenant, 'credit_tracking')
            .where({
                client_id: clientId,
                tenant
            });

        // Create a map of transaction IDs to credit tracking entries for quick lookup
        const trackingEntriesByTransactionId = new Map<string, ICreditTracking>();
        creditTrackingEntries.forEach(entry => {
            trackingEntriesByTransactionId.set(entry.transaction_id, entry);
        });

        // Find transactions that don't have corresponding credit tracking entries
        const missingTrackingEntries = transactions.filter(tx =>
            !trackingEntriesByTransactionId.has(tx.transaction_id)
        );

        // If there are missing tracking entries, create reconciliation reports
        for (const tx of missingTrackingEntries) {
            console.log(`Missing credit tracking entry for transaction ${tx.transaction_id} (${tx.type}) with amount ${tx.amount}`);

            // Create a reconciliation report for the missing tracking entry (or refresh the existing open one)
            const report = await upsertOpenReconciliationReport(trx, tenant, {
                client_id: clientId,
                expected_balance: 0, // Not applicable for this type of report
                actual_balance: 0,   // Not applicable for this type of report
                difference: 0,       // Not applicable for this type of report
                detection_date: now,
                // Store additional metadata about the missing tracking entry
                metadata: {
                    issue_type: 'missing_credit_tracking_entry',
                    transaction_id: tx.transaction_id,
                    transaction_type: tx.type,
                    transaction_amount: tx.amount,
                    transaction_date: tx.created_at,
                    reconciliation_date_basis: 'financial_document_date',
                }
            });

            reportIds.push(report.report_id);

            // Log the issue detection in the audit log
            await auditLog(
                trx,
                {
                    userId: 'system',
                    operation: 'missing_credit_tracking_entry_detected',
                    tableName: 'credit_reconciliation_reports',
                    recordId: report.report_id,
                    changedData: {
                        transaction_id: tx.transaction_id,
                        transaction_type: tx.type,
                        transaction_amount: tx.amount
                    },
                    details: {
                        action: 'Missing credit tracking entry detected',
                        client_id: clientId
                    }
                }
            );
        }

        return {
            isValid: missingTrackingEntries.length === 0,
            missingEntries: missingTrackingEntries.length,
            reportIds
        };
    };

    // If a transaction is provided, use it; otherwise create a new one
    if (providedTrx) {
        return await executeWithTransaction(providedTrx);
    } else {
        return await withTransaction(knex, executeWithTransaction);
    }
}

/**
 * Validates credit tracking remaining amounts for consistency
 * Creates reconciliation reports for any discrepancies found
 *
 * NOTE: This function requires tenant context to be set via runWithTenant() or withAuth wrapper.
 *
 * @param clientId The ID of the client to validate
 * @param providedTrx Optional transaction object
 * @returns Object containing validation results and report IDs if discrepancies were found
 */
export async function validateCreditTrackingRemainingAmounts(
    clientId: string,
    providedTrx?: Knex.Transaction
): Promise<{
    isValid: boolean;
    inconsistentEntries: number;
    reportIds: string[];
}> {
    const tenant = requireTenant();
    const { knex } = await createTenantKnex();

    // Use provided transaction or create a new one
    const executeWithTransaction = async (trx: Knex.Transaction) => {
        const now = new Date().toISOString();
        const reportIds: string[] = [];

        // Get all active (non-expired) credit tracking entries for this client
        const creditTrackingEntries = await tenantScopedTable(trx, tenant, 'credit_tracking')
            .where({
                client_id: clientId,
                tenant,
                is_expired: false
            })
            .where(function () {
                this.whereNull('expiration_date')
                    .orWhere('expiration_date', '>', now);
            });

        const inconsistentEntries: Array<{
            entry: ICreditTracking;
            expectedRemainingAmount: number;
            applications: Array<{
                transaction_id: string;
                amount: number;
                created_at: string;
            }>;
        }> = [];

        // For each credit tracking entry, calculate the expected remaining amount
        for (const entry of creditTrackingEntries) {
            // Get the original transaction
            const originalTransaction = await tenantScopedTable(trx, tenant, 'transactions')
                .where({
                    transaction_id: entry.transaction_id,
                    tenant
                })
                .first();

            if (!originalTransaction) {
                console.log(`Original transaction ${entry.transaction_id} not found for credit tracking entry ${entry.credit_id}`);
                continue;
            }

            // Get all credit application transactions related to this credit
            const applications = await tenantScopedTable(trx, tenant, 'transactions')
                .where({
                    tenant,
                    type: 'credit_application'
                })
                .where('related_transaction_id', entry.transaction_id)
                .orderBy('created_at', 'asc');

            const originalInvoiceContext = await loadCreditInvoiceContext(trx, tenant, originalTransaction.invoice_id);
            const applicationInvoiceContexts = new Map<string, CreditInvoicePeriodSummary | null>();

            for (const application of applications) {
                applicationInvoiceContexts.set(
                    application.transaction_id,
                    await loadCreditInvoiceContext(trx, tenant, application.invoice_id)
                );
            }

            // Calculate the expected remaining amount based on the original amount minus all applications
            let expectedRemainingAmount = Number(originalTransaction.amount);

            for (const application of applications) {
                // Credit applications have negative amounts (they reduce the credit)
                expectedRemainingAmount += Number(application.amount); // This will subtract since amount is negative
            }

            // If the credit is expired, the remaining amount should be 0
            if (entry.is_expired || (entry.expiration_date && entry.expiration_date < now)) {
                expectedRemainingAmount = 0;
            }

            // Round to 2 decimal places to avoid floating point comparison issues
            expectedRemainingAmount = Math.round(expectedRemainingAmount * 100) / 100;
            const actualRemainingAmount = Math.round(Number(entry.remaining_amount) * 100) / 100;

            // If the expected remaining amount doesn't match the actual remaining amount
            if (expectedRemainingAmount !== actualRemainingAmount) {
                console.log(`Inconsistent remaining amount for credit ${entry.credit_id}: expected ${expectedRemainingAmount}, actual ${actualRemainingAmount}`);

                inconsistentEntries.push({
                    entry,
                    expectedRemainingAmount,
                    applications: applications.map(app => ({
                        transaction_id: app.transaction_id,
                        amount: app.amount,
                        created_at: app.created_at
                    }))
                });

                // Create a reconciliation report for the inconsistent remaining amount (or refresh the existing open one)
                const report = await upsertOpenReconciliationReport(trx, tenant, {
                    client_id: clientId,
                    expected_balance: expectedRemainingAmount,
                    actual_balance: actualRemainingAmount,
                    difference: expectedRemainingAmount - actualRemainingAmount,
                    detection_date: now,
                    // Store additional metadata about the inconsistent remaining amount
                    metadata: {
                        issue_type: 'inconsistent_credit_remaining_amount',
                        reconciliation_date_basis: 'financial_document_date',
                        credit_id: entry.credit_id,
                        transaction_id: entry.transaction_id,
                        original_amount: originalTransaction.amount,
                        source_invoice_date_basis: originalInvoiceContext?.invoice_date_basis,
                        source_invoice_service_period_start: originalInvoiceContext?.invoice_service_period_start,
                        source_invoice_service_period_end: originalInvoiceContext?.invoice_service_period_end,
                        applications: applications.map(app => ({
                            transaction_id: app.transaction_id,
                            amount: app.amount,
                            created_at: app.created_at,
                            invoice_date_basis: applicationInvoiceContexts.get(app.transaction_id)?.invoice_date_basis,
                            invoice_service_period_start: applicationInvoiceContexts.get(app.transaction_id)?.invoice_service_period_start,
                            invoice_service_period_end: applicationInvoiceContexts.get(app.transaction_id)?.invoice_service_period_end,
                        }))
                    }
                });

                reportIds.push(report.report_id);

                // Log the issue detection in the audit log
                await auditLog(
                    trx,
                    {
                        userId: 'system',
                        operation: 'inconsistent_credit_remaining_amount_detected',
                        tableName: 'credit_reconciliation_reports',
                        recordId: report.report_id,
                        changedData: {
                            credit_id: entry.credit_id,
                            expected_remaining_amount: expectedRemainingAmount,
                            actual_remaining_amount: actualRemainingAmount,
                            difference: expectedRemainingAmount - actualRemainingAmount
                        },
                        details: {
                            action: 'Inconsistent credit remaining amount detected',
                            client_id: clientId
                        }
                    }
                );
            }
        }

        return {
            isValid: inconsistentEntries.length === 0,
            inconsistentEntries: inconsistentEntries.length,
            reportIds
        };
    };

    // If a transaction is provided, use it; otherwise create a new one
    if (providedTrx) {
        return await executeWithTransaction(providedTrx);
    } else {
        return await withTransaction(knex, executeWithTransaction);
    }
}

